WITH base AS (SELECT id, account_type, balance, opened_date, COALESCE(balance, 0) AS balance_filled, SUBSTRING(status, 1, 3) AS status_prefix FROM accounts WHERE account_type IN ('SAVINGS', 'LOAN')) SELECT id, account_type, balance, opened_date, balance_filled, LAG(balance) OVER (PARTITION BY account_type ORDER BY balance, id) AS prev_balance, LAG(balance_filled) OVER (PARTITION BY account_type ORDER BY balance, id) AS prev_balance_filled, ROW_NUMBER() OVER (PARTITION BY account_type ORDER BY balance, id) AS row_seq, SUM(balance) OVER (PARTITION BY account_type ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance FROM base
